// ==========================================
// EXTRACT & VALIDATE METADATA
// ==========================================

const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};

// Extract basic data
const sessionId = body.sessionId || body.metadata?.sessionId || 'unknown_session';
const chatInput = body.chatInput || '';
const metadata = body.metadata || {};

// Extract user data
const userData = metadata.userData || {};
const userName = userData.name || null;
const userPhone = userData.phone || null;
const userEmail = userData.email || null;

// Extract current product
const currentProduct = metadata.currentProduct || null;

// Extract page context
const pageType = metadata.pageType || 'other';
const pageUrl = metadata.pageUrl || '';
const pageTitle = metadata.pageTitle || '';
const timeOnPage = metadata.timeOnPage || 0;

// Extract browsing history
const viewedProducts = metadata.viewedProducts || [];
const isReturningToProduct = metadata.isReturningToProduct || false;

// Extract technical data
const referrer = metadata.referrer || null;
const userAgent = metadata.userAgent || headers['user-agent'] || null;
const timestamp = metadata.timestamp || Date.now();

// Extract IP address from headers (for geolocation)
// Check various headers where IP might be
let clientIp = headers['x-forwarded-for'] 
  || headers['x-real-ip'] 
  || headers['cf-connecting-ip']  // Cloudflare
  || headers['x-client-ip']
  || null;

// x-forwarded-for can contain multiple IPs, get the first one
if (clientIp && clientIp.includes(',')) {
  clientIp = clientIp.split(',')[0].trim();
}

// Check if we have contact info
const hasContactInfo = !!(userName && userPhone);

// Check if on product page
const isOnProductPage = pageType === 'product' && currentProduct !== null;

return {
  // Original message
  chatInput,
  sessionId,

  // User data
  userData: {
    name: userName,
    phone: userPhone,
    email: userEmail
  },
  hasContactInfo,

  // Current product
  currentProduct,
  isOnProductPage,

  // Page context
  pageType,
  pageUrl,
  pageTitle,
  timeOnPage,

  // Browsing history
  viewedProducts,
  isReturningToProduct,

  // Technical
  clientIp,
  referrer,
  userAgent,
  timestamp,

  // Raw for later use
  _raw: body
};
